jwt-decoder.formula:
token = base64url(header) + "." + base64url(payload) + "." + base64url(signature)
header:  { "alg": "HS256", "typ": "JWT" }
payload: { "sub": "1234567890", "name": "Asha", "iat": 1792281600, "exp": 1792368000 }
sign:    HMAC-SHA256(secret, header_b64 + "." + payload_b64)
decode:  JSON.parse(base64urlDecode(part))   // no key needed
verify:  recompute signature, compare bytes   // needs the secret
